/**
 * 外壳模板 · AppProviders（ADR 0009）：把根路由上散着的外壳契约收进一个组件。
 *
 *   <AppProviders linkAdapter={…}>{页面}</AppProviders>
 *
 * 收进的东西：
 * - LinkAdapterProvider（ADR 0005）。linkAdapter 必填：漏传时 tsc 报 TS2741，运行时也抛错。
 * - 主题偏好：next-themes 的 ThemeProvider 在挂载后补应用偏好，注册表的 Toaster 据此跟随主题。
 *   首屏之前的那一步靠 THEME_INIT_SCRIPT（见 theme-script.ts），AppProviders 管不到。
 * - TooltipProvider、Toaster、skip-link（与 AppShell 共用 MAIN_ID）。
 * - 开发态检测：上面这些降级类契约缺失时 console.error，每条只报一次。
 *
 * 放在路由库的 Provider 之内（TanStack Router 下即 __root.tsx 的组件）。
 * 共享 Biome 配置要求根路由文件 __root.tsx 渲染 <AppProviders>。
 * 本文件不认识任何业务作用域（#17）。
 */

import { ThemeProvider } from "next-themes";
import { createContext, type ReactNode, use, useEffect, useLayoutEffect } from "react";
import { Toaster } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { type LinkAdapter, LinkAdapterProvider, useLinkAdapter } from "./link-adapter";
import {
  assertLinkAdapter,
  createDevReporter,
  createMountCounter,
  findShellProblems,
  IS_DEV,
  MAIN_ID,
  readShellState,
  SKIP_LINK_HREF,
} from "./shell-contracts";
import { THEME_INIT_ATTRIBUTE, THEME_INIT_SCRIPT, THEME_STORAGE_KEY } from "./theme-script";

export { MAIN_ID, THEME_INIT_SCRIPT };

export interface AppProvidersProps {
  /** 链接适配对象（ADR 0005）。没有路由的场景（如单元测试）传一个假的适配对象。 */
  linkAdapter: LinkAdapter;
  children: ReactNode;
  /** skip-link 的文案。 */
  skipLinkLabel?: string;
}

/**
 * next-themes 自带的内联脚本在客户端渲染时不会执行，React 19 还会为它报错。
 * 首屏脚本由 THEME_INIT_SCRIPT 负责，所以把它标成数据块，让 React 跳过。
 */
const THEME_SCRIPT_PROPS = { type: "application/json" } as const;

export function AppProviders({
  linkAdapter,
  children,
  skipLinkLabel = "跳到主要内容",
}: AppProvidersProps) {
  assertLinkAdapter(linkAdapter);
  return (
    <ThemeProvider
      attribute="class"
      storageKey={THEME_STORAGE_KEY}
      defaultTheme="system"
      enableSystem
      disableTransitionOnChange
      scriptProps={THEME_SCRIPT_PROPS}
    >
      <LinkAdapterProvider adapter={linkAdapter}>
        <TooltipProviderWithMark>
          <SkipLink label={skipLinkLabel} />
          {children}
          <ToasterWithMark />
          <ShellContractCheck />
        </TooltipProviderWithMark>
      </LinkAdapterProvider>
    </ThemeProvider>
  );
}

/** 跳到 <main id={MAIN_ID}>。用内置的 sr-only / not-sr-only，不需要额外的 @utility。 */
function SkipLink({ label }: { label: string }) {
  return (
    <a
      href={SKIP_LINK_HREF}
      className="sr-only rounded-md border border-border bg-background px-3 py-2 text-sm font-medium text-foreground shadow-lg focus:not-sr-only focus:fixed focus:top-2 focus:left-2 focus:z-50 focus:px-3 focus:py-2 focus:outline-none focus:ring-2 focus:ring-ring"
    >
      {label}
    </a>
  );
}

const TooltipMark = createContext(false);

/** TooltipProvider 加一个标记：开发态检测据此判断外壳是否在它之内。 */
function TooltipProviderWithMark({ children }: { children: ReactNode }) {
  return (
    <TooltipProvider>
      <TooltipMark value={true}>{children}</TooltipMark>
    </TooltipProvider>
  );
}

const toasters = createMountCounter();

/** 注册表的 Toaster（主题跟随 next-themes）加挂载计数：开发态检测据此判断它是否挂上。 */
function ToasterWithMark() {
  useLayoutEffect(() => toasters.mount(), []);
  return <Toaster />;
}

const report = createDevReporter({
  enabled: IS_DEV,
  log: (message) => console.error(message),
});

/** 挂载后与每次换路径后检查降级类契约。只在开发态工作。 */
function ShellContractCheck() {
  const tooltipProvider = use(TooltipMark);
  const { pathname } = useLinkAdapter();
  // biome-ignore lint/correctness/useExhaustiveDependencies: 换路径后页面换了，DOM 要重查一遍。
  useEffect(() => {
    if (!IS_DEV) return;
    const state = readShellState(document, {
      tooltipProvider,
      toasters: toasters.count(),
      themeInit: document.documentElement.hasAttribute(THEME_INIT_ATTRIBUTE),
    });
    report(findShellProblems(state));
  }, [tooltipProvider, pathname]);
  return null;
}

/**
 * 外壳模板 · AppShell：侧栏（顶部插槽 + 数据驱动的导航 + 底部插槽）、页头（面包屑 + 动作插槽）、
 * 可选的副面板、内容区（换页时播进场动画）。
 *
 * - 不认识任何业务作用域（#17）：侧栏顶部、底部都是通用插槽；面包屑有几级、每级是什么，由传入的数据决定。
 * - 导航项只认已解析的 href 字符串；当前项按 match 计算，缺省 "exact"（ADR 0005）。
 *   链接与当前路径都从 useLinkAdapter() 读，本文件不 import 任何路由库。
 * - 进场动画的 key 取适配对象的 transitionKey，缺省为路径加路径参数，查询参数变化不重播（ADR 0005）。
 * - 动效由 motion 属性选预设（ADR 0021）：motion.page 是换页的进场（fade／slide-up，缺省 fade），
 *   motion.nav 是侧栏选中项的底色（spring／none，缺省 spring：底色以弹簧从上一项移到新项，用 motion 库的 layoutId）。
 * - <main id={MAIN_ID}> 与 AppProviders 的 skip-link 配对。
 * - themeToggle 为 true 时，页头最右边放主题切换（ThemeToggle，圆形揭开新主题，ADR 0021）。
 * - 必须渲染在 <AppProviders> 之内。
 */

import { Columns2Icon } from "lucide-react";
import { motion as animated, useReducedMotion } from "motion/react";
import { Fragment, type ReactNode, useEffect, useId, useRef, useState } from "react";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { Button } from "@/components/ui/button";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarRail,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar";
import {
  isNavItemActive,
  type NavMatchTarget,
  transitionKeyOf,
  useLinkAdapter,
} from "./link-adapter";
import { MAIN_ID } from "./shell-contracts";
import { ThemeToggle } from "./theme-toggle";

export interface AppShellNavItem extends NavMatchTarget {
  key: string;
  label: string;
  /** 图标由消费者给（lucide-react）。侧栏收起时只剩图标，label 进 tooltip。 */
  icon?: ReactNode;
}

export interface AppShellNavGroup {
  key: string;
  /** 分组标题。只有一组时可以不写。 */
  label?: string;
  items: readonly AppShellNavItem[];
}

/** 面包屑的一级。最后一级不写 href，表示当前页。 */
export interface AppShellCrumb {
  label: string;
  href?: string;
}

/** 外壳自带的文案。缺省为简体中文，按产品语言覆盖。 */
export interface AppShellCopy {
  breadcrumb: string;
  secondaryPanel: string;
  toggleSecondaryPanel: string;
  switchToDark: string;
  switchToLight: string;
}

/**
 * 换页进场的动效预设（ADR 0021）。缺省 `fade`。
 * - `fade`：新页面淡入，150ms。
 * - `slide-up`：新页面从下方 16px 升起并淡入，220ms。
 */
export type AppShellPageMotion = "fade" | "slide-up";

/**
 * 侧栏选中项的动效预设（ADR 0021）。缺省 `spring`。
 * - `spring`：选中的底色以弹簧从上一项移到新项（motion 库的 layoutId，刚度 520、阻尼 40）。
 * - `none`：底色直接跳到新项（Sidebar 原装的选中态）。
 */
export type AppShellNavMotion = "none" | "spring";

/** 外壳里会动的两处：换页（page）与侧栏选中项（nav）。 */
export interface AppShellMotion {
  page: AppShellPageMotion;
  nav: AppShellNavMotion;
}

const DEFAULT_MOTION: AppShellMotion = { page: "fade", nav: "spring" };

/** 侧栏选中项的弹簧：取 aidevstack 侧栏的手感，快而不过冲。 */
const NAV_SPRING = { type: "spring", stiffness: 520, damping: 40 } as const;

const DEFAULT_COPY: AppShellCopy = {
  breadcrumb: "面包屑",
  secondaryPanel: "副面板",
  toggleSecondaryPanel: "切换副面板",
  switchToDark: "切换到深色模式",
  switchToLight: "切换到浅色模式",
};

export interface AppShellProps {
  /** 导航数据。权限过滤在消费者一侧做完再传进来。 */
  nav: readonly AppShellNavGroup[];
  /** 侧栏顶部的通用插槽：品牌、切换器等，放什么由消费者决定。 */
  sidebarHeader?: ReactNode;
  /** 侧栏底部的通用插槽：常放当前用户菜单。 */
  sidebarFooter?: ReactNode;
  /** 面包屑。层级完全由数据决定；不传就不渲染。 */
  breadcrumbs?: readonly AppShellCrumb[];
  /** 页头右侧的动作插槽。 */
  headerActions?: ReactNode;
  /** 在页头最右边放主题切换（ThemeToggle）。缺省不放；要放在别处就自己渲染 ThemeToggle。 */
  themeToggle?: boolean;
  /** 副面板（SecondaryPanel）的内容，如模块树。不传就没有副面板。 */
  secondaryPanel?: ReactNode;
  /** 侧栏初始是否展开。SSR 下由消费者从 cookie 读出再传，否则刷新时会闪一下。 */
  defaultSidebarOpen?: boolean;
  /** 副面板初始是否展开（宽屏）。 */
  defaultSecondaryPanelOpen?: boolean;
  copy?: Partial<AppShellCopy>;
  /** 动效预设：换页 `page`（缺省 `fade`）与侧栏选中项 `nav`（缺省 `spring`）。只写要改的一项。 */
  motion?: Partial<AppShellMotion>;
  children: ReactNode;
}

export function AppShell({
  nav,
  sidebarHeader,
  sidebarFooter,
  breadcrumbs,
  headerActions,
  themeToggle = false,
  secondaryPanel,
  defaultSidebarOpen = true,
  defaultSecondaryPanelOpen = true,
  copy: copyOverrides,
  motion: motionOverrides,
  children,
}: AppShellProps) {
  const copy = { ...DEFAULT_COPY, ...copyOverrides };
  const motion = { ...DEFAULT_MOTION, ...motionOverrides };
  // 选中项底色的共享身份：同一时刻只有一项渲染它，motion 库把它当成同一个元素在移动。
  // 带上 useId，页面上有两个外壳（如文档站的演示）时互不干扰。
  const navIndicatorId = `app-shell-nav-${useId()}`;
  return (
    <SidebarProvider defaultOpen={defaultSidebarOpen}>
      <Sidebar collapsible="icon">
        {sidebarHeader ? <SidebarHeader>{sidebarHeader}</SidebarHeader> : null}
        <SidebarContent>
          {nav.map((group) => (
            <AppShellNavGroupView
              key={group.key}
              group={group}
              motion={motion.nav}
              indicatorId={navIndicatorId}
            />
          ))}
        </SidebarContent>
        {sidebarFooter ? <SidebarFooter>{sidebarFooter}</SidebarFooter> : null}
        <SidebarRail />
      </Sidebar>
      <SidebarInset id={MAIN_ID} tabIndex={-1} className="grid grid-rows-header-body outline-none">
        <SecondaryPanelLayout
          panel={secondaryPanel}
          defaultOpen={defaultSecondaryPanelOpen}
          copy={copy}
          header={(panelTrigger) => (
            <header className="sticky top-0 z-10 flex h-12 items-center gap-2 border-b border-border bg-background px-3">
              <SidebarTrigger />
              {panelTrigger}
              {breadcrumbs && breadcrumbs.length > 0 ? (
                <AppShellBreadcrumbs crumbs={breadcrumbs} label={copy.breadcrumb} />
              ) : null}
              <div className="ml-auto flex items-center gap-2">
                {headerActions}
                {themeToggle ? (
                  <ThemeToggle
                    switchToDarkLabel={copy.switchToDark}
                    switchToLightLabel={copy.switchToLight}
                  />
                ) : null}
              </div>
            </header>
          )}
        >
          <PageTransition motion={motion.page}>{children}</PageTransition>
        </SecondaryPanelLayout>
      </SidebarInset>
    </SidebarProvider>
  );
}

function AppShellNavGroupView({
  group,
  motion,
  indicatorId,
}: {
  group: AppShellNavGroup;
  motion: AppShellNavMotion;
  indicatorId: string;
}) {
  const { Link, pathname } = useLinkAdapter();
  const spring = motion === "spring";
  return (
    <SidebarGroup>
      {group.label ? <SidebarGroupLabel>{group.label}</SidebarGroupLabel> : null}
      <SidebarMenu>
        {group.items.map((item) => {
          const active = isNavItemActive(item, pathname);
          return (
            <SidebarMenuItem key={item.key} className={spring ? "isolate" : undefined}>
              {spring && active ? <NavActiveIndicator layoutId={indicatorId} /> : null}
              <SidebarMenuButton
                isActive={active}
                tooltip={item.label}
                className={spring ? "data-active:bg-transparent" : undefined}
                render={<Link href={item.href} aria-current={active ? "page" : undefined} />}
              >
                {item.icon}
                <span>{item.label}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          );
        })}
      </SidebarMenu>
    </SidebarGroup>
  );
}

/**
 * 侧栏选中项的底色（motion.nav = "spring"）。画在导航项（li）里、按钮下面（-z-10，li 是 isolate），
 * 所以按钮的选中底色改成透明。不放进按钮里：按钮 overflow-hidden，会把移动中的底色裁掉。
 * CSS 做不到：底色要从上一项的位置连续移到新项，两项是不同的元素，只有 layout 动画能接上（ADR 0021）。
 * reduced-motion 下时长为 0，直接到位。
 */
function NavActiveIndicator({ layoutId }: { layoutId: string }) {
  const reduce = useReducedMotion() === true;
  return (
    <animated.span
      layoutId={layoutId}
      aria-hidden="true"
      data-slot="app-shell-nav-indicator"
      data-motion="spring"
      className="absolute inset-0 -z-10 bg-sidebar-accent"
      transition={reduce ? { duration: 0 } : NAV_SPRING}
    />
  );
}

function AppShellBreadcrumbs({
  crumbs,
  label,
}: {
  crumbs: readonly AppShellCrumb[];
  label: string;
}) {
  const { Link } = useLinkAdapter();
  return (
    <Breadcrumb aria-label={label} className="min-w-0">
      <BreadcrumbList>
        {crumbs.map((crumb, index) => (
          <Fragment key={`${crumb.href ?? ""}|${crumb.label}`}>
            {index > 0 ? <BreadcrumbSeparator /> : null}
            <BreadcrumbItem>
              {crumb.href === undefined ? (
                <BreadcrumbPage>{crumb.label}</BreadcrumbPage>
              ) : (
                <BreadcrumbLink render={<Link href={crumb.href} />}>{crumb.label}</BreadcrumbLink>
              )}
            </BreadcrumbItem>
          </Fragment>
        ))}
      </BreadcrumbList>
    </Breadcrumb>
  );
}

/**
 * 副面板（#19 归外壳）：宽屏是内容区左边的一列，窄屏是从左边滑出的抽屉。
 * 没有 panel 时不渲染副面板与它的开关。
 */
function SecondaryPanelLayout({
  panel,
  defaultOpen,
  copy,
  header,
  children,
}: {
  panel: ReactNode;
  defaultOpen: boolean;
  copy: AppShellCopy;
  header: (panelTrigger: ReactNode) => ReactNode;
  children: ReactNode;
}) {
  const { isMobile } = useSidebar();
  const [open, setOpen] = useState(defaultOpen);
  const [openMobile, setOpenMobile] = useState(false);
  const hasPanel = Boolean(panel);
  // 有没有副面板，树的形状都不变：否则进出「用例」这类路由时内容区会整块重挂，进场动画也丢了。
  const trigger = hasPanel ? (
    <Button
      variant="ghost"
      size="icon-sm"
      aria-label={copy.toggleSecondaryPanel}
      aria-expanded={isMobile ? openMobile : open}
      onClick={() => (isMobile ? setOpenMobile((value) => !value) : setOpen((value) => !value))}
    >
      <Columns2Icon />
    </Button>
  ) : null;
  return (
    <>
      {header(trigger)}
      <div className="flex min-w-0">
        {hasPanel && open && !isMobile ? (
          <aside
            aria-label={copy.secondaryPanel}
            className="hidden w-64 shrink-0 border-r border-border md:block"
          >
            {panel}
          </aside>
        ) : null}
        <div className="min-w-0 flex-1">{children}</div>
      </div>
      {hasPanel && isMobile ? (
        <Sheet open={openMobile} onOpenChange={setOpenMobile}>
          <SheetContent side="left" className="w-72 p-0">
            <SheetHeader className="sr-only">
              <SheetTitle>{copy.secondaryPanel}</SheetTitle>
              <SheetDescription>{copy.secondaryPanel}</SheetDescription>
            </SheetHeader>
            {panel}
          </SheetContent>
        </Sheet>
      ) : null}
    </>
  );
}

/**
 * 内容区是撑满剩余高度的 flex 列：页面根元素写 flex-1 就能占满它（列表模板的空态靠这一点撑满高度）。
 * `*:w-full` 让直接子元素仍像块级元素一样占满宽度：`mx-auto max-w-3xl` 这类居中的页面不会缩成内容宽度。
 */
const CONTENT_COLUMN = "flex min-h-full flex-col *:w-full";

/**
 * 换页时的进场动画。transitionKey 变化时重挂内容，新元素带 data-motion，由基础层的 @starting-style 播一次入场；
 * 首屏不带 data-motion，不播。reduced-motion 下 slide-up 不上移，只淡入（ADR 0021）。
 */
function PageTransition({ motion, children }: { motion: AppShellPageMotion; children: ReactNode }) {
  const transitionKey = transitionKeyOf(useLinkAdapter());
  const mounted = useRef(false);
  useEffect(() => {
    mounted.current = true;
  }, []);
  return (
    <div
      key={transitionKey}
      data-transition-key={transitionKey}
      data-motion={mounted.current ? motion : undefined}
      className={CONTENT_COLUMN}
    >
      {children}
    </div>
  );
}

/**
 * 链接适配（ADR 0005、0015）：模板借以接入消费者路由的注入点。
 * 本文件不 import 任何路由库。消费者在路由 Provider 之内挂 <LinkAdapterProvider>，
 * 模板用 useLinkAdapter() 读取。
 */
import {
  type ComponentType,
  createContext,
  type MouseEvent,
  type ReactNode,
  type Ref,
  use,
} from "react";
import type { LinkAdapterParams } from "./nav-match";

export type { LinkAdapterParams, NavMatch, NavMatchTarget } from "./nav-match";
export { isNavItemActive, pathOfHref, transitionKeyOf } from "./nav-match";

/**
 * 适配对象的 Link 收到的 props。href 是宿主已解析好的字符串。
 * 外壳用 `render={<Link …/>}` 把链接交给 Base UI，Base UI 会传进 onClick 与 ref（React 19 里 ref 是普通 prop）。
 * 自写的 Link 必须把两者转发到 <a>：onClick 先调用，再接管点击；ref 原样交给 <a>。
 */
export interface LinkAdapterLinkProps {
  href: string;
  className?: string;
  "aria-current"?: "page";
  children?: ReactNode;
  onClick?: (event: MouseEvent<HTMLAnchorElement>) => void;
  ref?: Ref<HTMLAnchorElement>;
}

export type LinkAdapterNavigate = (href: string, options?: { replace?: boolean }) => void;

/** useNavigationBlocker 的返回值。blocked 为 true 时，用户确认后调 proceed，取消时调 reset。 */
export interface NavigationBlocker {
  blocked: boolean;
  proceed(): void;
  reset(): void;
}

export interface LinkAdapter {
  /** 渲染链接。 */
  Link: ComponentType<LinkAdapterLinkProps>;
  /** 当前路径，不含查询参数。 */
  pathname: string;
  /** 当前路由的路径参数。 */
  params: LinkAdapterParams;
  /** 命令式跳转。 */
  navigate: LinkAdapterNavigate;
  /** 可选：PageTransition 的 key。缺省为路径加路径参数，见 transitionKeyOf。 */
  transitionKey?: string;
  /**
   * 可选：拦截站内跳转（ADR 0015）。它是 hook，同一个适配对象要么一直提供，要么一直不提供。
   * 没有这一项时，表单模板只挂 beforeunload，并在开发态 console.error 一次。
   */
  useNavigationBlocker?: (shouldBlock: boolean) => NavigationBlocker;
}

const LinkAdapterContext = createContext<LinkAdapter | null>(null);

export function LinkAdapterProvider({
  adapter,
  children,
}: {
  adapter: LinkAdapter;
  children: ReactNode;
}) {
  return <LinkAdapterContext value={adapter}>{children}</LinkAdapterContext>;
}

/** 读链接适配。读不到 Provider 时抛错：漏挂 Provider 是硬依赖缺失（ADR 0009）。 */
export function useLinkAdapter(): LinkAdapter {
  const adapter = use(LinkAdapterContext);
  if (adapter === null) {
    throw new Error(
      "useLinkAdapter 必须在 <LinkAdapterProvider> 之内使用：请在根路由挂上 <LinkAdapterProvider adapter={…}>。",
    );
  }
  return adapter;
}

/**
 * 链接适配的纯逻辑：导航项的当前项计算与 transitionKey 缺省值（ADR 0005）。
 * 不 import React，也不 import 任何路由库。
 */

/** 当前项的计算规则。缺省 "exact"；父级导航要在子路由保持高亮时显式写 "prefix"。 */
export type NavMatch = "exact" | "prefix" | ((pathname: string) => boolean);

/** 导航项里参与当前项计算的字段。href 是宿主已解析好的字符串。 */
export interface NavMatchTarget {
  href: string;
  match?: NavMatch;
  /** 覆盖 match：给了就直接用它。 */
  isActive?: boolean;
}

export type LinkAdapterParams = Readonly<Record<string, string | undefined>>;

/** 去掉 href 里的查询参数与 hash，只留路径。 */
export function pathOfHref(href: string): string {
  const end = href.search(/[?#]/);
  return end === -1 ? href : href.slice(0, end);
}

function trimTrailingSlash(path: string): string {
  return path.length > 1 && path.endsWith("/") ? path.slice(0, -1) : path;
}

export function isNavItemActive(item: NavMatchTarget, pathname: string): boolean {
  if (item.isActive !== undefined) return item.isActive;
  const match = item.match ?? "exact";
  if (typeof match === "function") return match(pathname);
  const href = trimTrailingSlash(pathOfHref(item.href));
  const path = trimTrailingSlash(pathname);
  if (path === href) return true;
  if (match === "exact") return false;
  // 按路径段比较：/reports 不命中 /reports-archive。"/" 用 prefix 会命中一切。
  return path.startsWith(href === "/" ? href : `${href}/`);
}

/** PageTransition 的 key：适配对象给了就用它，否则用路径加路径参数。查询参数不参与。 */
export function transitionKeyOf(adapter: {
  pathname: string;
  params: LinkAdapterParams;
  transitionKey?: string;
}): string {
  if (adapter.transitionKey !== undefined) return adapter.transitionKey;
  const params = Object.keys(adapter.params)
    .filter((key) => adapter.params[key] !== undefined)
    .sort()
    .map((key) => [key, adapter.params[key]]);
  return `${adapter.pathname}#${JSON.stringify(params)}`;
}

/**
 * 外壳隐式契约的纯逻辑（ADR 0009）：MAIN_ID 配对、链接适配的硬检查、降级类契约的开发态检测。
 * 不 import React，也不 import 任何路由库。AppProviders 与 AppShell 共用这里的常量。
 *
 * 检测分两级：
 * - 硬依赖（链接适配）缺失：assertLinkAdapter 抛错，生产环境也抛。
 * - 只是降级（TooltipProvider、Toaster、主题脚本、skip-link）：findShellProblems 找出来，
 *   createDevReporter 在开发态 console.error，每条只报一次。依赖外壳的模板复用 IS_DEV 与 createDevReporter。
 */
/** skip-link 与 AppShell 的 <main> 共用这一个 id：配对在模板内部闭合。 */
export const MAIN_ID = "main";

/** skip-link 的 href。 */
export const SKIP_LINK_HREF = `#${MAIN_ID}`;

/** 判断是否开发态。用字面的 process.env.NODE_ENV，Vite 与 webpack 都会在构建时替换它。 */
declare const process: { env: { NODE_ENV?: string } };
export const IS_DEV = process.env.NODE_ENV !== "production";

const REQUIRED_ADAPTER_FIELDS = ["Link", "pathname", "params", "navigate"] as const;

/**
 * 链接适配是硬依赖：漏传或缺必备字段时抛错。
 * 类型上 linkAdapter 已是必填（漏传时 tsc 报 TS2741）；这里兜住 JS 调用方与 as 断言绕过类型的情况。
 */
export function assertLinkAdapter(adapter: unknown): void {
  if (adapter === null || adapter === undefined) {
    throw new Error(
      "<AppProviders> 缺少 linkAdapter：请传入链接适配对象，例如 <AppProviders linkAdapter={useTanStackLinkAdapter()}>（ADR 0005、0009）。没有路由的场景传一个假的适配对象。",
    );
  }
  const record = adapter as Record<string, unknown>;
  const missing = REQUIRED_ADAPTER_FIELDS.filter((field) => record[field] === undefined);
  if (missing.length > 0) {
    throw new Error(
      `linkAdapter 缺少必备字段：${missing.join("、")}。链接适配要有 Link、pathname、params、navigate 四样（ADR 0005）。`,
    );
  }
}

/** 降级类契约的现状。前三项由 AppProviders 从 context、挂载计数与 <html> 的标记得到，其余从 DOM 读。 */
export interface ShellState {
  /** 当前组件是否在 AppProviders 的 TooltipProvider 之内。 */
  tooltipProvider: boolean;
  /** 已挂载的 AppProviders Toaster 个数。 */
  toasters: number;
  /** 首屏之前是否跑过 THEME_INIT_SCRIPT。 */
  themeInit: boolean;
  /** id 为 MAIN_ID 的元素个数。 */
  mainTargets: number;
  /** 指向 MAIN_ID 的 skip-link 个数。 */
  skipLinks: number;
}

/** readShellState 用到的 document 子集，便于测试时替换。 */
export interface ShellDocument {
  querySelectorAll(selector: string): { length: number };
}

export function readShellState(
  doc: ShellDocument,
  known: Pick<ShellState, "tooltipProvider" | "toasters" | "themeInit">,
): ShellState {
  return {
    ...known,
    mainTargets: doc.querySelectorAll(`[id="${MAIN_ID}"]`).length,
    skipLinks: doc.querySelectorAll(`a[href="${SKIP_LINK_HREF}"]`).length,
  };
}

export interface ShellProblem {
  id: string;
  message: string;
}

export function findShellProblems(state: ShellState): ShellProblem[] {
  const problems: ShellProblem[] = [];
  if (!state.tooltipProvider) {
    problems.push({
      id: "tooltip-provider",
      message:
        "外壳不在 AppProviders 的 TooltipProvider 之内：tooltip 仍会出现，但打开延迟回落到 600ms，相邻 tooltip 不再瞬开。请恢复 app-providers.tsx 里的 <TooltipProviderWithMark>。",
    });
  }
  if (state.toasters === 0) {
    problems.push({
      id: "toaster",
      message:
        "页面上没有 AppProviders 的 <Toaster>：toast() 照常返回，但通知不会出现。请恢复 app-providers.tsx 里的 <ToasterWithMark />。",
    });
  } else if (state.toasters > 1) {
    problems.push({
      id: "toaster-duplicate",
      message: `页面上挂了 ${state.toasters} 个 <Toaster>：每条通知会出现多次。只保留 AppProviders 里的那一个。`,
    });
  }
  if (!state.themeInit) {
    problems.push({
      id: "theme-init",
      message:
        "首屏之前没有跑 THEME_INIT_SCRIPT：暗色偏好要等挂载后才补上，首屏会闪色。Vite SPA 在 vite.config.ts 里把它注入 index.html 的 <head>，SSR 放进根路由的 <head>。",
    });
  }
  if (state.mainTargets === 0) {
    problems.push({
      id: "main-missing",
      message: `页面上没有 id="${MAIN_ID}" 的元素：skip-link 无处可跳。用 <AppShell>，或在不用外壳的页面渲染 <main id={MAIN_ID}>。`,
    });
  } else if (state.mainTargets > 1) {
    problems.push({
      id: "main-duplicate",
      message: `页面上有 ${state.mainTargets} 个 id="${MAIN_ID}" 的元素：skip-link 只会跳到第一个。页面内容里不要再写 id={MAIN_ID}。`,
    });
  }
  if (state.skipLinks === 0) {
    problems.push({
      id: "skip-link",
      message: `页面上没有指向 ${SKIP_LINK_HREF} 的 skip-link：键盘用户无法跳过导航。请恢复 app-providers.tsx 里的 <SkipLink />。`,
    });
  }
  return problems;
}

/**
 * 开发态 console.error，同一个 id 只报一次。enabled 为 false 时什么都不做。
 * 依赖应用外壳的模板（表单、详情、设置）也用它报自己的降级，`scope` 写模板名，作为消息前缀，缺省 `"app-shell"`。
 */
export function createDevReporter({
  enabled,
  log,
  scope = "app-shell",
}: {
  enabled: boolean;
  log: (message: string) => void;
  scope?: string;
}): (problems: readonly ShellProblem[]) => void {
  const reported = new Set<string>();
  return (problems) => {
    if (!enabled) return;
    for (const problem of problems) {
      if (reported.has(problem.id)) continue;
      reported.add(problem.id);
      log(`[${scope}] ${problem.message}`);
    }
  };
}

/** 挂载计数：Toaster 挂载时加一，卸载时减一。 */
export function createMountCounter(): { mount(): () => void; count(): number } {
  let mounted = 0;
  return {
    mount() {
      mounted += 1;
      let done = false;
      return () => {
        if (done) return;
        done = true;
        mounted -= 1;
      };
    },
    count: () => mounted,
  };
}

/**
 * 主题初始化脚本（ADR 0009）。本文件没有任何 import，可以在 vite.config.ts 与 SSR 的 <head> 里直接引用。
 *
 * AppProviders 渲染在 <body> 里，管不到首屏之前；首屏之前按偏好挂好 .dark 只能靠这段内联脚本：
 * - Vite SPA：在 vite.config.ts 用 transformIndexHtml 注入 index.html 的 <head>。
 * - SSR：在根路由的 <head> 里渲染 <script dangerouslySetInnerHTML={{ __html: THEME_INIT_SCRIPT }} />。
 *
 * 脚本与 AppProviders 里 next-themes 的设置一致：localStorage 键 "theme"，值 light / dark / system，
 * 在 <html> 上挂 .light 或 .dark 并设 color-scheme。它另打一个标记属性，
 * AppProviders 在开发态据此确认脚本在首屏之前跑过。
 */

/** localStorage 里存主题偏好的键。与 next-themes 的缺省值相同。 */
export const THEME_STORAGE_KEY = "theme";

/** 脚本跑过的标记，打在 <html> 上。 */
export const THEME_INIT_ATTRIBUTE = "data-theme-init";

const DARK_QUERY = "(prefers-color-scheme: dark)";

/** 内联到 <head> 的脚本正文。不依赖任何全局变量之外的东西，读不到 localStorage 时跟随系统偏好。 */
export const THEME_INIT_SCRIPT = `(function(){var d=document.documentElement,t=null;try{t=localStorage.getItem(${JSON.stringify(THEME_STORAGE_KEY)})}catch(e){}if(t!=="light"&&t!=="dark")t=matchMedia(${JSON.stringify(DARK_QUERY)}).matches?"dark":"light";d.classList.remove("light","dark");d.classList.add(t);d.style.colorScheme=t;d.setAttribute(${JSON.stringify(THEME_INIT_ATTRIBUTE)},"")})()`;

/**
 * 外壳模板 · ThemeToggle：在浅色与深色之间切换，以点击位置为圆心揭开新主题（ADR 0021 的 reveal 预设）。
 *
 * - AppShell 传 `themeToggle` 时把它放在页头最右边；要放在别处（如用户菜单旁）就直接渲染本组件。
 * - 主题偏好由 AppProviders 里的 next-themes 管：本组件只调 setTheme，不另存状态。
 * - 不支持 View Transitions 或开了 reduced-motion 时直接切换（见 theme-transition.ts）。
 * - 必须渲染在 <AppProviders> 之内。
 */

import { MoonIcon, SunIcon } from "lucide-react";
import { useTheme } from "next-themes";
import { flushSync } from "react-dom";
import { Button } from "@/components/ui/button";
import { runThemeTransition } from "./theme-transition";

export interface ThemeToggleProps {
  /** 当前是浅色时的按钮名称。 */
  switchToDarkLabel?: string;
  /** 当前是深色时的按钮名称。 */
  switchToLightLabel?: string;
}

export function ThemeToggle({
  switchToDarkLabel = "切换到深色模式",
  switchToLightLabel = "切换到浅色模式",
}: ThemeToggleProps) {
  const { resolvedTheme, setTheme } = useTheme();
  const dark = resolvedTheme === "dark";
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      aria-label={dark ? switchToLightLabel : switchToDarkLabel}
      onClick={(event) => {
        // 键盘触发的 click 没有坐标（detail 为 0），圆心退回按钮中心。
        const origin = event.detail > 0 ? { x: event.clientX, y: event.clientY } : null;
        void runThemeTransition(() => flushSync(() => setTheme(dark ? "light" : "dark")), {
          origin,
          element: event.currentTarget,
        });
      }}
    >
      {dark ? <SunIcon /> : <MoonIcon />}
    </Button>
  );
}

/**
 * 外壳模板 · 主题切换的圆形揭开（ADR 0021 的 reveal 预设）。本文件没有任何 import，`node --test` 直接测。
 *
 * 以点击位置为圆心，新主题从一个圆里长出来，盖满视口。用 View Transitions API：浏览器先给旧主题拍一张快照，
 * 回调里换主题，再拍新主题；动画只裁剪新快照（clip-path），在合成器上跑，几百个节点换色也不掉帧。
 *
 * 不支持 View Transitions、开了 reduced-motion、或上一次还没播完时，直接换主题，不做动画。
 * 时长与曲线读基础层的 --motion-reveal-duration 与 --motion-ease-enter（reduced-motion 下时长是 0）。
 */

export interface Point {
  x: number;
  y: number;
}

export interface Viewport {
  width: number;
  height: number;
}

export interface ThemeTransitionOptions {
  /** 点击坐标。键盘触发时不传（click 事件的 detail 为 0，坐标没有意义）。 */
  origin?: Point | null;
  /** 触发元素：没有点击坐标时取它的中心。 */
  element?: Element | null;
}

/** 揭开的缺省时长（毫秒），与 base.css 的 --motion-reveal-duration 一致；读不到该变量时用它。 */
export const REVEAL_DURATION = 600;

/** 圆心：点击坐标 > 触发元素的中心 > 视口中心，并夹进视口。 */
export function revealCenter(
  origin: Point | null | undefined,
  rect: { left: number; top: number; width: number; height: number } | null | undefined,
  viewport: Viewport,
): Point {
  const x = origin?.x ?? (rect ? rect.left + rect.width / 2 : viewport.width / 2);
  const y = origin?.y ?? (rect ? rect.top + rect.height / 2 : viewport.height / 2);
  return {
    x: Math.min(Math.max(x, 0), viewport.width),
    y: Math.min(Math.max(y, 0), viewport.height),
  };
}

/** 盖满视口所需的半径：圆心到最远那个角的距离。 */
export function revealRadius(center: Point, viewport: Viewport): number {
  return Math.hypot(
    Math.max(center.x, viewport.width - center.x),
    Math.max(center.y, viewport.height - center.y),
  );
}

/** 揭开动画的 clip-path 起止帧。 */
export function revealKeyframes(center: Point, radius: number): [string, string] {
  const at = `at ${center.x}px ${center.y}px`;
  return [`circle(0px ${at})`, `circle(${radius}px ${at})`];
}

/** 要不要播揭开动画：浏览器支持、没开 reduced-motion、时长为正、没有正在播的一次。 */
export function shouldReveal({
  supported,
  reduced,
  duration,
  running,
}: {
  supported: boolean;
  reduced: boolean;
  duration: number;
  running: boolean;
}): boolean {
  return supported && !reduced && duration > 0 && !running;
}

/** CSS 时长文本 → 毫秒：`600ms` → 600，`0.6s` → 600；读不懂返回 null。 */
export function parseDuration(text: string | null | undefined): number | null {
  const match = /^\s*([\d.]+)(ms|s)\s*$/.exec(text ?? "");
  if (!match) return null;
  const value = Number(match[1]) * (match[2] === "s" ? 1000 : 1);
  return Number.isFinite(value) ? value : null;
}

const STYLE_ID = "app-shell-theme-reveal";
/** 揭开期间关掉浏览器缺省的交叉淡化：旧快照原地不动，只裁剪新快照。 */
const STYLE_TEXT =
  "::view-transition-old(root),::view-transition-new(root){animation:none;mix-blend-mode:normal}";

let running = false;

type ViewTransitionDocument = Document & {
  startViewTransition?: (callback: () => void) => {
    ready: Promise<void>;
    finished: Promise<void>;
  };
};

/**
 * 在揭开动画里执行 apply（真正换主题的那一步）。apply 必须同步把新主题写进 DOM：
 * 用 React 状态换主题时，在 apply 里用 flushSync，否则浏览器拍新快照时还是旧主题。
 */
export async function runThemeTransition(
  apply: () => void,
  options: ThemeTransitionOptions = {},
): Promise<void> {
  const doc = document as ViewTransitionDocument;
  const root = doc.documentElement;
  const style = getComputedStyle(root);
  const duration =
    parseDuration(style.getPropertyValue("--motion-reveal-duration")) ?? REVEAL_DURATION;
  const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
  if (
    !shouldReveal({
      supported: typeof doc.startViewTransition === "function",
      reduced,
      duration,
      running,
    })
  ) {
    apply();
    return;
  }
  const viewport = { width: window.innerWidth, height: window.innerHeight };
  const center = revealCenter(options.origin, options.element?.getBoundingClientRect(), viewport);
  const easing = style.getPropertyValue("--motion-ease-enter").trim() || "ease-out";
  const css = doc.createElement("style");
  css.id = STYLE_ID;
  css.textContent = STYLE_TEXT;
  doc.head.appendChild(css);
  running = true;
  let applied = false;
  const update = () => {
    applied = true;
    apply();
  };
  try {
    const transition = doc.startViewTransition?.(update);
    if (!transition) return;
    await transition.ready;
    root.animate(
      { clipPath: revealKeyframes(center, revealRadius(center, viewport)) },
      { duration, easing, pseudoElement: "::view-transition-new(root)" },
    );
    await transition.finished;
  } catch {
    // 过渡被跳过（例如页面隐藏）时 ready 会 reject，回调照样执行过；回调没跑过就在这里补上。
    if (!applied) apply();
  } finally {
    css.remove();
    running = false;
  }
}
